     // at each store and shrink it judges.
     using TypePairCache = flat_map<pair<TypeExpr *, TypeExpr *>, bool>;
     TypePairCache cancontain, reachesthrough;
+    // Only stable type exclusions, never roots or live reference provenance.
+    // Globals and their definitions are fixed after parsing. Initializers must
+    // finish before an entry can omit a non-reference global permanently.
+    bool globalinitializersdone = false;
+    using GlobalRootFilter = vector<pair<VarDecl *, VarDef *>>;
+    flat_map<TypeExpr *, GlobalRootFilter> globalrootfilters;
     bool library = false;   // Built for a C host (--header): fn main() is optional.
     bool nomain = false;    // Checking only: a file without fn main() is checked on its own.

