         for (auto t : ast.alltypes) {
--- a/src/typecheck_types.h
+++ b/src/typecheck_types.h
@@ -1307,11 +1307,34 @@
     };
     if (!globalsonly) VisibleVars([&](VarDef *v) { if (!v->isglobal) consider(v, d); });
     auto unchecked = false;
-    for (auto g : ast.globals)
-        for (auto gd : g->defs) {
-            consider(gd, 0);
-            unchecked = unchecked || (!gd->type && !(g->type && IsRefOrSlice(g->type)));
-        }
+    auto global = [&](VarDecl *g, VarDef *gd) {
+        consider(gd, 0);
+        unchecked = unchecked || (!gd->type && !(g->type && IsRefOrSlice(g->type)));
+    };
+    if (globalinitializersdone && !typesbuilding && stablecontainment.Identity(of)) {
+        auto filter = globalrootfilters.find(of);
+        if (!filter) {
+            GlobalRootFilter pending;
+            for (auto g : ast.globals)
+                for (auto gd : g->defs) {
+                    // An excluded global contributes nothing: globals are not
+                    // parameters, and this branch has no reference provenance.
+                    // Keep all unfinished/failed/view globals in the live scan.
+                    if (gd->type && !IsRefOrSlice(gd->type) &&
+                        !failedglobals.count(gd) && stablecontainment.Ready(gd->type) &&
+                        !CanContain(gd->type, of)) continue;
+                    pending.push_back({ g, gd });
+                }
+            // Publish only after the complete filter was built. Remaining
+            // entries keep AST order; each is reconsidered with its live state.
+            filter = &globalrootfilters[of];
+            *filter = std::move(pending);
+        }
+        for (auto [g, gd] : *filter) global(g, gd);
+    } else {
+        for (auto g : ast.globals)
+            for (auto gd : g->defs) global(g, gd);
+    }
     // A writable reference or slice is never given static data but a null or an
     // empty slice (§9.5: literals only go into const slots), which point at no
     // storage, so static data does not stand beside a real candidate for one.
